// Hand-written `@trpc/tanstack-react-query` stub for the flowatlas fixture suite.
//
// The newer bindings hand the proxy back from a hook, and its leaves make options
// for the query library rather than running a query themselves. Declared by kind,
// as the other stubs are: members by any name, leaves that answer the factories.

export interface OptionsNode {
  queryOptions(input?: unknown): unknown;
  mutationOptions(): unknown;
  [name: string]: OptionsNode | ((input?: unknown) => unknown);
}

export declare function createTRPCContext<TRouter>(): {
  TRPCProvider: (props: { children?: unknown }) => unknown;
  useTRPC: () => Record<string, OptionsNode>;
};
